#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

