@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

