:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
