@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse property for containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse property for hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is section of" ;
    rdfs:comment "Inverse property for hasSection." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is involved in message" ;
    rdfs:comment "Inverse property for involvesOrganization." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role played by" ;
    rdfs:comment "Inverse property for playsRole." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse property for hasRole." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse property for hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Inverse property for hasIdentifier." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of detail section" ;
    rdfs:comment "Inverse property for hasItem." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is described by line item" ;
    rdfs:comment "Inverse property for describesItem." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is net price of line item" ;
    rdfs:comment "Inverse property for hasNetPrice." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "is quantity of line item" ;
    rdfs:comment "Inverse property for hasQuantity." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of summary section" ;
    rdfs:comment "Inverse property for hasTax." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "is total amount of summary section" ;
    rdfs:comment "Inverse property for hasTotalAmount." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process of invoice message" ;
    rdfs:comment "Inverse property for assignedToProcess." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is validation constraint of invoice message" ;
    rdfs:comment "Inverse property for conformsToStandard." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is warehouse address of organization" ;
    rdfs:comment "Inverse property for hasWarehouseAddress." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is reference document of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceDocument." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is allowance/charge of invoice message" ;
    rdfs:comment "Inverse property for hasAllowanceCharge." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is transport details of invoice message" ;
    rdfs:comment "Inverse property for hasTransportDetails." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "is price details of line item" ;
    rdfs:comment "Inverse property for hasPriceDetails." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "is duty/tax/fee details of line item" ;
    rdfs:comment "Inverse property for hasDutyTaxFeeDetails." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "is package of line item" ;
    rdfs:comment "Inverse property for hasPackage." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "is additional product ID of item" ;
    rdfs:comment "Inverse property for hasAdditionalProductID." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
    rdfs:comment "Links an item to its description (IMD segment)." ;
    owl:inverseOf :isItemDescriptionOfItem .

:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "is item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :VATBreakdown ;
    rdfs:label "has VAT breakdown" ;
    rdfs:comment "Links the summary section to its VAT breakdown (EN 16931-1)." ;
    owl:inverseOf :isVATBreakdownOfSummarySection .

:isVATBreakdownOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :VATBreakdown ;
    rdfs:range :SummarySection ;
    rdfs:label "is VAT breakdown of summary section" ;
    rdfs:comment "Inverse property for hasVATBreakdown." .

:hasPaymentTerms a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :PaymentTerms ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links the header section to payment terms." ;
    owl:inverseOf :isPaymentTermsOfHeaderSection .

:isPaymentTermsOfHeaderSection a owl:ObjectProperty ;
    rdfs:domain :PaymentTerms ;
    rdfs:range :HeaderSection ;
    rdfs:label "is payment terms of header section" ;
    rdfs:comment "Inverse property for hasPaymentTerms." .

:hasDocumentTotals a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :DocumentTotals ;
    rdfs:label "has document totals" ;
    rdfs:comment "Links the summary section to document-level totals (EN 16931-1)." ;
    owl:inverseOf :isDocumentTotalsOfSummarySection .

:isDocumentTotalsOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :DocumentTotals ;
    rdfs:range :SummarySection ;
    rdfs:label "is document totals of summary section" ;
    rdfs:comment "Inverse property for hasDocumentTotals." .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "GLN identifier for an organization/location." .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the document." .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

#################################################################
# INDIVIDUALS (OPTIONAL, OMITTED FOR STRUCTURE)
#################################################################

# ...

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse property for containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse property for hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is section of" ;
    rdfs:comment "Inverse property for hasSection." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is involved in message" ;
    rdfs:comment "Inverse property for involvesOrganization." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role played by" ;
    rdfs:comment "Inverse property for playsRole." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse property for hasRole." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse property for hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Inverse property for hasIdentifier." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of detail section" ;
    rdfs:comment "Inverse property for hasItem." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is described by line item" ;
    rdfs:comment "Inverse property for describesItem." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is net price of line item" ;
    rdfs:comment "Inverse property for hasNetPrice." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "is quantity of line item" ;
    rdfs:comment "Inverse property for hasQuantity." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of summary section" ;
    rdfs:comment "Inverse property for hasTax." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "is total amount of summary section" ;
    rdfs:comment "Inverse property for hasTotalAmount." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process of invoice message" ;
    rdfs:comment "Inverse property for assignedToProcess." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is validation constraint of invoice message" ;
    rdfs:comment "Inverse property for conformsToStandard." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is warehouse address of organization" ;
    rdfs:comment "Inverse property for hasWarehouseAddress." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is reference document of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceDocument." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is allowance/charge of invoice message" ;
    rdfs:comment "Inverse property for hasAllowanceCharge." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is transport details of invoice message" ;
    rdfs:comment "Inverse property for hasTransportDetails." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "is price details of line item" ;
    rdfs:comment "Inverse property for hasPriceDetails." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "is duty/tax/fee details of line item" ;
    rdfs:comment "Inverse property for hasDutyTaxFeeDetails." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "is package of line item" ;
    rdfs:comment "Inverse property for hasPackage." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "is additional product ID of item" ;
    rdfs:comment "Inverse property for hasAdditionalProductID." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
    rdfs:comment "Links an item to its description (IMD segment)." ;
    owl:inverseOf :isItemDescriptionOfItem .

:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "is item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :VATBreakdown ;
    rdfs:label "has VAT breakdown" ;
    rdfs:comment "Links the summary section to its VAT breakdown (EN 16931-1)." ;
    owl:inverseOf :isVATBreakdownOfSummarySection .

:isVATBreakdownOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :VATBreakdown ;
    rdfs:range :SummarySection ;
    rdfs:label "is VAT breakdown of summary section" ;
    rdfs:comment "Inverse property for hasVATBreakdown." .

:hasPaymentTerms a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :PaymentTerms ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links the header section to payment terms." ;
    owl:inverseOf :isPaymentTermsOfHeaderSection .

:isPaymentTermsOfHeaderSection a owl:ObjectProperty ;
    rdfs:domain :PaymentTerms ;
    rdfs:range :HeaderSection ;
    rdfs:label "is payment terms of header section" ;
    rdfs:comment "Inverse property for hasPaymentTerms." .

:hasDocumentTotals a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :DocumentTotals ;
    rdfs:label "has document totals" ;
    rdfs:comment "Links the summary section to document-level totals (EN 16931-1)." ;
    owl:inverseOf :isDocumentTotalsOfSummarySection .

:isDocumentTotalsOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :DocumentTotals ;
    rdfs:range :SummarySection ;
    rdfs:label "is document totals of summary section" ;
    rdfs:comment "Inverse property for hasDocumentTotals." .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "GLN identifier for an organization/location." .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the document." .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

#################################################################
# INDIVIDUALS (OPTIONAL, OMITTED FOR STRUCTURE)
#################################################################

# ...

@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse property for containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse property for hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is section of" ;
    rdfs:comment "Inverse property for hasSection." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is involved in message" ;
    rdfs:comment "Inverse property for involvesOrganization." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role played by" ;
    rdfs:comment "Inverse property for playsRole." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse property for hasRole." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse property for hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Inverse property for hasIdentifier." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of detail section" ;
    rdfs:comment "Inverse property for hasItem." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is described by line item" ;
    rdfs:comment "Inverse property for describesItem." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is net price of line item" ;
    rdfs:comment "Inverse property for hasNetPrice." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "is quantity of line item" ;
    rdfs:comment "Inverse property for hasQuantity." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of summary section" ;
    rdfs:comment "Inverse property for hasTax." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "is total amount of summary section" ;
    rdfs:comment "Inverse property for hasTotalAmount." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process of invoice message" ;
    rdfs:comment "Inverse property for assignedToProcess." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is validation constraint of invoice message" ;
    rdfs:comment "Inverse property for conformsToStandard." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is warehouse address of organization" ;
    rdfs:comment "Inverse property for hasWarehouseAddress." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is reference document of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceDocument." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is allowance/charge of invoice message" ;
    rdfs:comment "Inverse property for hasAllowanceCharge." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is transport details of invoice message" ;
    rdfs:comment "Inverse property for hasTransportDetails." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "is price details of line item" ;
    rdfs:comment "Inverse property for hasPriceDetails." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "is duty/tax/fee details of line item" ;
    rdfs:comment "Inverse property for hasDutyTaxFeeDetails." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "is package of line item" ;
    rdfs:comment "Inverse property for hasPackage." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "is additional product ID of item" ;
    rdfs:comment "Inverse property for hasAdditionalProductID." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
    rdfs:comment "Links an item to its description (IMD segment)." ;
    owl:inverseOf :isItemDescriptionOfItem .

:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "is item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :VATBreakdown ;
    rdfs:label "has VAT breakdown" ;
    rdfs:comment "Links the summary section to its VAT breakdown (EN 16931-1)." ;
    owl:inverseOf :isVATBreakdownOfSummarySection .

:isVATBreakdownOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :VATBreakdown ;
    rdfs:range :SummarySection ;
    rdfs:label "is VAT breakdown of summary section" ;
    rdfs:comment "Inverse property for hasVATBreakdown." .

:hasPaymentTerms a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :PaymentTerms ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links the header section to payment terms." ;
    owl:inverseOf :isPaymentTermsOfHeaderSection .

:isPaymentTermsOfHeaderSection a owl:ObjectProperty ;
    rdfs:domain :PaymentTerms ;
    rdfs:range :HeaderSection ;
    rdfs:label "is payment terms of header section" ;
    rdfs:comment "Inverse property for hasPaymentTerms." .

:hasDocumentTotals a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :DocumentTotals ;
    rdfs:label "has document totals" ;
    rdfs:comment "Links the summary section to document-level totals (EN 16931-1)." ;
    owl:inverseOf :isDocumentTotalsOfSummarySection .

:isDocumentTotalsOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :DocumentTotals ;
    rdfs:range :SummarySection ;
    rdfs:label "is document totals of summary section" ;
    rdfs:comment "Inverse property for hasDocumentTotals." .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "GLN identifier for an organization/location." .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the document." .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

#################################################################
# INDIVIDUALS (OPTIONAL, OMITTED FOR STRUCTURE)
#################################################################

# ...

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." ;
    rdfs:subClassOf :Identifier .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "contained in envelope" ;
    rdfs:comment "Inverse property for containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "segment of message" ;
    rdfs:comment "Inverse property for hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "section of invoice message" ;
    rdfs:comment "Inverse property for hasSection." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "composite element of segment" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "simple element of composite" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "involved in invoice message" ;
    rdfs:comment "Inverse property for involvesOrganization." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "role played by organization" ;
    rdfs:comment "Inverse property for playsRole." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "role of assignment" ;
    rdfs:comment "Inverse property for hasRole." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "address of organization" ;
    rdfs:comment "Inverse property for hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "identifier of organization" ;
    rdfs:comment "Inverse property for hasIdentifier." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "line item of detail section" ;
    rdfs:comment "Inverse property for hasItem." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "described by line item" ;
    rdfs:comment "Inverse property for describesItem." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "net price of line item" ;
    rdfs:comment "Inverse property for hasNetPrice." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "quantity of line item" ;
    rdfs:comment "Inverse property for hasQuantity." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "tax of summary section" ;
    rdfs:comment "Inverse property for hasTax." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "total amount of summary section" ;
    rdfs:comment "Inverse property for hasTotalAmount." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "business process of invoice message" ;
    rdfs:comment "Inverse property for assignedToProcess." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "validation constraint of invoice message" ;
    rdfs:comment "Inverse property for conformsToStandard." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "warehouse address of organization" ;
    rdfs:comment "Inverse property for hasWarehouseAddress." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "reference document of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceDocument." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "allowance/charge of invoice message" ;
    rdfs:comment "Inverse property for hasAllowanceCharge." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "transport details of invoice message" ;
    rdfs:comment "Inverse property for hasTransportDetails." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "price details of line item" ;
    rdfs:comment "Inverse property for hasPriceDetails." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "duty/tax/fee details of line item" ;
    rdfs:comment "Inverse property for hasDutyTaxFeeDetails." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "package of line item" ;
    rdfs:comment "Inverse property for hasPackage." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "additional product ID of item" ;
    rdfs:comment "Inverse property for hasAdditionalProductID." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
    rdfs:comment "Links an item to its description (IMD segment)." ;
    owl:inverseOf :isItemDescriptionOfItem .

:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :VATBreakdown ;
    rdfs:label "has VAT breakdown" ;
    rdfs:comment "Links the summary section to its VAT breakdown (EN 16931-1)." ;
    owl:inverseOf :isVATBreakdownOfSummarySection .

:isVATBreakdownOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :VATBreakdown ;
    rdfs:range :SummarySection ;
    rdfs:label "VAT breakdown of summary section" ;
    rdfs:comment "Inverse property for hasVATBreakdown." .

:hasPaymentTerms a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :PaymentTerms ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links the header section to payment terms." ;
    owl:inverseOf :isPaymentTermsOfHeaderSection .

:isPaymentTermsOfHeaderSection a owl:ObjectProperty ;
    rdfs:domain :PaymentTerms ;
    rdfs:range :HeaderSection ;
    rdfs:label "payment terms of header section" ;
    rdfs:comment "Inverse property for hasPaymentTerms." .

:hasDocumentTotals a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :DocumentTotals ;
    rdfs:label "has document totals" ;
    rdfs:comment "Links the summary section to document-level totals (EN 16931-1)." ;
    owl:inverseOf :isDocumentTotalsOfSummarySection .

:isDocumentTotalsOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :DocumentTotals ;
    rdfs:range :SummarySection ;
    rdfs:label "document totals of summary section" ;
    rdfs:comment "Inverse property for hasDocumentTotals." .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "GLN identifier for an organization/location." .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the document." .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

#################################################################
# INDIVIDUALS (OPTIONAL, OMITTED FOR STRUCTURE)
#################################################################

# ...

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." ;
    rdfs:subClassOf :Identifier .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "contained in envelope" ;
    rdfs:comment "Inverse property for containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "segment of message" ;
    rdfs:comment "Inverse property for hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "section of invoice message" ;
    rdfs:comment "Inverse property for hasSection." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "composite element of segment" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "simple element of composite" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "involved in invoice message" ;
    rdfs:comment "Inverse property for involvesOrganization." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "role played by organization" ;
    rdfs:comment "Inverse property for playsRole." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "role of assignment" ;
    rdfs:comment "Inverse property for hasRole." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "address of organization" ;
    rdfs:comment "Inverse property for hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "identifier of organization" ;
    rdfs:comment "Inverse property for hasIdentifier." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "line item of detail section" ;
    rdfs:comment "Inverse property for hasItem." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "described by line item" ;
    rdfs:comment "Inverse property for describesItem." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "net price of line item" ;
    rdfs:comment "Inverse property for hasNetPrice." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "quantity of line item" ;
    rdfs:comment "Inverse property for hasQuantity." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "tax of summary section" ;
    rdfs:comment "Inverse property for hasTax." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "total amount of summary section" ;
    rdfs:comment "Inverse property for hasTotalAmount." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "business process of invoice message" ;
    rdfs:comment "Inverse property for assignedToProcess." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "validation constraint of invoice message" ;
    rdfs:comment "Inverse property for conformsToStandard." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "warehouse address of organization" ;
    rdfs:comment "Inverse property for hasWarehouseAddress." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "reference document of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceDocument." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "allowance/charge of invoice message" ;
    rdfs:comment "Inverse property for hasAllowanceCharge." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "transport details of invoice message" ;
    rdfs:comment "Inverse property for hasTransportDetails." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "price details of line item" ;
    rdfs:comment "Inverse property for hasPriceDetails." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "duty/tax/fee details of line item" ;
    rdfs:comment "Inverse property for hasDutyTaxFeeDetails." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "package of line item" ;
    rdfs:comment "Inverse property for hasPackage." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "additional product ID of item" ;
    rdfs:comment "Inverse property for hasAdditionalProductID." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
    rdfs:comment "Links an item to its description (IMD segment)." ;
    owl:inverseOf :isItemDescriptionOfItem .

:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :VATBreakdown ;
    rdfs:label "has VAT breakdown" ;
    rdfs:comment "Links the summary section to its VAT breakdown (EN 16931-1)." ;
    owl:inverseOf :isVATBreakdownOfSummarySection .

:isVATBreakdownOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :VATBreakdown ;
    rdfs:range :SummarySection ;
    rdfs:label "VAT breakdown of summary section" ;
    rdfs:comment "Inverse property for hasVATBreakdown." .

:hasPaymentTerms a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :PaymentTerms ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links the header section to payment terms." ;
    owl:inverseOf :isPaymentTermsOfHeaderSection .

:isPaymentTermsOfHeaderSection a owl:ObjectProperty ;
    rdfs:domain :PaymentTerms ;
    rdfs:range :HeaderSection ;
    rdfs:label "payment terms of header section" ;
    rdfs:comment "Inverse property for hasPaymentTerms." .

:hasDocumentTotals a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :DocumentTotals ;
    rdfs:label "has document totals" ;
    rdfs:comment "Links the summary section to document-level totals (EN 16931-1)." ;
    owl:inverseOf :isDocumentTotalsOfSummarySection .

:isDocumentTotalsOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :DocumentTotals ;
    rdfs:range :SummarySection ;
    rdfs:label "document totals of summary section" ;
    rdfs:comment "Inverse property for hasDocumentTotals." .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "GLN identifier for an organization/location." .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the document." .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

#################################################################
# INDIVIDUALS (OPTIONAL, OMITTED FOR STRUCTURE)
#################################################################

# ...

@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." ;
    rdfs:subClassOf :Identifier .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "contained in envelope" ;
    rdfs:comment "Inverse property for containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "segment of message" ;
    rdfs:comment "Inverse property for hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "section of invoice message" ;
    rdfs:comment "Inverse property for hasSection." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "composite element of segment" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "simple element of composite" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "involved in invoice message" ;
    rdfs:comment "Inverse property for involvesOrganization." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "role played by organization" ;
    rdfs:comment "Inverse property for playsRole." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "role of assignment" ;
    rdfs:comment "Inverse property for hasRole." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "address of organization" ;
    rdfs:comment "Inverse property for hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "identifier of organization" ;
    rdfs:comment "Inverse property for hasIdentifier." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "line item of detail section" ;
    rdfs:comment "Inverse property for hasItem." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "described by line item" ;
    rdfs:comment "Inverse property for describesItem." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "net price of line item" ;
    rdfs:comment "Inverse property for hasNetPrice." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "quantity of line item" ;
    rdfs:comment "Inverse property for hasQuantity." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "tax of summary section" ;
    rdfs:comment "Inverse property for hasTax." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "total amount of summary section" ;
    rdfs:comment "Inverse property for hasTotalAmount." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "business process of invoice message" ;
    rdfs:comment "Inverse property for assignedToProcess." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "validation constraint of invoice message" ;
    rdfs:comment "Inverse property for conformsToStandard." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "warehouse address of organization" ;
    rdfs:comment "Inverse property for hasWarehouseAddress." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "reference document of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceDocument." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "allowance/charge of invoice message" ;
    rdfs:comment "Inverse property for hasAllowanceCharge." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "transport details of invoice message" ;
    rdfs:comment "Inverse property for hasTransportDetails." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "price details of line item" ;
    rdfs:comment "Inverse property for hasPriceDetails." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "duty/tax/fee details of line item" ;
    rdfs:comment "Inverse property for hasDutyTaxFeeDetails." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "package of line item" ;
    rdfs:comment "Inverse property for hasPackage." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "additional product ID of item" ;
    rdfs:comment "Inverse property for hasAdditionalProductID." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
    rdfs:comment "Links an item to its description (IMD segment)." ;
    owl:inverseOf :isItemDescriptionOfItem .

:isItemDescriptionOfItem a owl:ObjectProperty ;
    rdfs:domain :ItemDescription ;
    rdfs:range :Item ;
    rdfs:label "item description of item" ;
    rdfs:comment "Inverse property for hasItemDescription." .

:hasVATBreakdown a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :VATBreakdown ;
    rdfs:label "has VAT breakdown" ;
    rdfs:comment "Links the summary section to its VAT breakdown (EN 16931-1)." ;
    owl:inverseOf :isVATBreakdownOfSummarySection .

:isVATBreakdownOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :VATBreakdown ;
    rdfs:range :SummarySection ;
    rdfs:label "VAT breakdown of summary section" ;
    rdfs:comment "Inverse property for hasVATBreakdown." .

:hasPaymentTerms a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :PaymentTerms ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links the header section to payment terms." ;
    owl:inverseOf :isPaymentTermsOfHeaderSection .

:isPaymentTermsOfHeaderSection a owl:ObjectProperty ;
    rdfs:domain :PaymentTerms ;
    rdfs:range :HeaderSection ;
    rdfs:label "payment terms of header section" ;
    rdfs:comment "Inverse property for hasPaymentTerms." .

:hasDocumentTotals a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :DocumentTotals ;
    rdfs:label "has document totals" ;
    rdfs:comment "Links the summary section to document-level totals (EN 16931-1)." ;
    owl:inverseOf :isDocumentTotalsOfSummarySection .

:isDocumentTotalsOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :DocumentTotals ;
    rdfs:range :SummarySection ;
    rdfs:label "document totals of summary section" ;
    rdfs:comment "Inverse property for hasDocumentTotals." .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "GLN identifier for an organization/location." .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the document." .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:Organization owl:disjointWith :Address .
:Organization owl:disjointWith :Identifier .
:Item owl:disjointWith :Price .
:Item owl:disjointWith :Tax .
:MonetaryAmount owl:disjointWith :Price .
:AllowanceCharge owl:disjointWith :MonetaryAmount .
:Quantity owl:disjointWith :MonetaryAmount .
:ReferenceDocument owl:disjointWith :DateTimePeriod .
:TransportDetails owl:disjointWith :AllowanceCharge .
:PriceDetails owl:disjointWith :DutyTaxFeeDetails .
:Package owl:disjointWith :PriceDetails .
:AdditionalProductID owl:disjointWith :ItemDescription .
:VATBreakdown owl:disjointWith :PaymentTerms .
:DocumentTotals owl:disjointWith :VATBreakdown .
:PriceDetailsSegment owl:disjointWith :TaxSegment .
:PackageSegment owl:disjointWith :PriceDetailsSegment .
:AdditionalProductIDSegment owl:disjointWith :ItemDescriptionSegment .

#################################################################
# INDIVIDUALS (OPTIONAL, OMITTED FOR STRUCTURE)
#################################################################

# ...

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC D96A Ontology" ;
    rdfs:comment "A profoundly structured OWL ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and attributes as per EN 16931-1 and P2P-O alignment." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message instance within an interchange envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural segment in an EDIFACT message (e.g., BGM, NAD, LIN, MOA, etc.)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing document identification and dates." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message, providing totals, taxes, and payment terms." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity participating in the invoice (buyer, supplier, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the business process (buyer, seller, etc.)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or legal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or document (e.g., GLN, VAT number)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value assigned to an item or line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax or duty applied to the invoice or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint or rule for validating invoice data (e.g., SHACL shape)." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot/reification class linking an organization to a specific role in a context (e.g., buyer, seller)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A standardized identifier for physical locations (GLN)." ;
    rdfs:subClassOf :Identifier .

:MonetaryAmount a owl:Class ;
    rdfs:subClassOf :MonetaryAmountSegment ;
    rdfs:label "Monetary Amount" ;
    rdfs:comment "A monetary value, as per MOA segment, such as line net, tax, or invoice total." .

:DateTimePeriod a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Date/Time Period" ;
    rdfs:comment "A date or period relevant to the document (e.g., invoice date)." .

:ReferenceDocument a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Reference Document" ;
    rdfs:comment "A referenced document (e.g., order, delivery note) in the invoice." .

:AllowanceCharge a owl:Class ;
    rdfs:subClassOf :AllowanceChargeSegment ;
    rdfs:label "Allowance/Charge" ;
    rdfs:comment "Discounts or surcharges applied at document or line level." .

:TransportDetails a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Transport Details" ;
    rdfs:comment "Information about transport arrangements (TOD segment)." .

:Quantity a owl:Class ;
    rdfs:subClassOf :QuantitySegment ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value as per QTY segment." .

:PriceDetails a owl:Class ;
    rdfs:subClassOf :PriceDetailsSegment ;
    rdfs:label "Price Details" ;
    rdfs:comment "Details of pricing at line or document level, as per PRI segment." .

:DutyTaxFeeDetails a owl:Class ;
    rdfs:subClassOf :TaxSegment ;
    rdfs:label "Duty/Tax/Fee Details" ;
    rdfs:comment "Details of tax, duty, or fee as per TAX segment." .

:Package a owl:Class ;
    rdfs:subClassOf :PackageSegment ;
    rdfs:label "Package" ;
    rdfs:comment "Packaging details as per PAC segment." .

:AdditionalProductID a owl:Class ;
    rdfs:subClassOf :AdditionalProductIDSegment ;
    rdfs:label "Additional Product ID" ;
    rdfs:comment "Alternative or additional identifiers for an item (PIA segment)." .

:ItemDescription a owl:Class ;
    rdfs:subClassOf :ItemDescriptionSegment ;
    rdfs:label "Item Description" ;
    rdfs:comment "Descriptive information about an item (IMD segment)." .

:VATBreakdown a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "VAT Breakdown" ;
    rdfs:comment "Breakdown of VAT rates and amounts per EN 16931-1." .

:PaymentTerms a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Payment Terms" ;
    rdfs:comment "Terms of payment for the invoice." .

:DocumentTotals a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Document Totals" ;
    rdfs:comment "Aggregated totals for the invoice as per EN 16931-1." .

# Segment-level classes for explicit modeling
:PriceDetailsSegment a owl:Class ;
    rdfs:label "Price Details Segment" ;
    rdfs:comment "Explicit PRI segment structure for price details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Explicit TAX segment structure for duty/tax/fee details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:PackageSegment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Explicit PAC segment structure for packaging details." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AdditionalProductIDSegment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Explicit PIA segment structure for additional product IDs." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:ItemDescriptionSegment a owl:Class ;
    rdfs:label "Item Description Segment" ;
    rdfs:comment "Explicit IMD segment structure for item descriptions." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Explicit MOA segment structure for monetary amounts." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Explicit QTY segment structure for quantities." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Explicit ALC segment structure for allowances/charges." ;
    rdfs:subClassOf :Segment ;
    rdfs:subClassOf :CompositeDataElement .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "Contained in Envelope" ;
    rdfs:comment "The message is contained in an interchange envelope (inverse of containsMessage)." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its constituent segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "Segment of Message" ;
    rdfs:comment "The segment is part of a message (inverse of hasSegment)." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Section of Invoice Message" ;
    rdfs:comment "The section belongs to an invoice message (inverse of hasSection)." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "Composite Element of Segment" ;
    rdfs:comment "The composite data element belongs to a segment (inverse of hasCompositeElement)." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "Simple Element of Composite Data Element" ;
    rdfs:comment "The simple data element is part of a composite data element (inverse of hasSimpleElement)." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Involved in Invoice Message" ;
    rdfs:comment "The organization is involved in the invoice message (inverse of involvesOrganization)." .

:playsRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignment(s)." ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "Role Played by Organization" ;
    rdfs:comment "The role assignment is played by an organization (inverse of playsRole)." .

:hasRole a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role played in a given assignment." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "Role of Assignment" ;
    rdfs:comment "The agent role is part of a role assignment (inverse of hasRole)." .

:hasAddress a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "Address of Organization" ;
    rdfs:comment "The address belongs to an organization (inverse of hasAddress)." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "Identifier of Organization" ;
    rdfs:comment "The identifier is associated with an organization (inverse of hasIdentifier)." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "Line Item of Detail Section" ;
    rdfs:comment "The line item is part of a detail section (inverse of hasItem)." .

:describesItem a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the item described." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "Described by Line Item" ;
    rdfs:comment "The item is described by a line item (inverse of describesItem)." .

:hasNetPrice a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "Net Price of Line Item" ;
    rdfs:comment "The price is the net price of a line item (inverse of hasNetPrice)." .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a line item to its quantity." ;
    owl:inverseOf :isQuantityOfLineItem .

:isQuantityOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem ;
    rdfs:label "Quantity of Line Item" ;
    rdfs:comment "The quantity is associated with a line item (inverse of hasQuantity)." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "Tax of Summary Section" ;
    rdfs:comment "The tax is associated with a summary section (inverse of hasTax)." .

:hasTotalAmount a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :MonetaryAmount ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links the summary section to the invoice total amount." ;
    owl:inverseOf :isTotalAmountOfSummarySection .

:isTotalAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :MonetaryAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "Total Amount of Summary Section" ;
    rdfs:comment "The monetary amount is the total for a summary section (inverse of hasTotalAmount)." .

:assignedToProcess a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessOfInvoiceMessage .

:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Business Process of Invoice Message" ;
    rdfs:comment "The business process is associated with the invoice message (inverse of assignedToProcess)." .

:conformsToStandard a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "conforms to standard" ;
    rdfs:comment "Indicates that the invoice conforms to a validation constraint or standard." ;
    owl:inverseOf :isValidationConstraintOfInvoiceMessage .

:isValidationConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Validation Constraint of Invoice Message" ;
    rdfs:comment "The validation constraint applies to the invoice message (inverse of conformsToStandard)." .

:hasWarehouseAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has warehouse address" ;
    rdfs:comment "Links an organization to its warehouse address." ;
    owl:inverseOf :isWarehouseAddressOfOrganization .

:isWarehouseAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "Warehouse Address of Organization" ;
    rdfs:comment "The warehouse address is associated with an organization (inverse of hasWarehouseAddress)." .

:hasReferenceDocument a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceDocument ;
    rdfs:label "has reference document" ;
    rdfs:comment "Links an invoice message to a referenced document (order, delivery note, etc.)." ;
    owl:inverseOf :isReferenceDocumentOfInvoiceMessage .

:isReferenceDocumentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceDocument ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Reference Document of Invoice Message" ;
    rdfs:comment "The reference document is associated with the invoice message (inverse of hasReferenceDocument)." .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceCharge ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an invoice message to allowances or charges." ;
    owl:inverseOf :isAllowanceChargeOfInvoiceMessage .

:isAllowanceChargeOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceCharge ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Allowance/Charge of Invoice Message" ;
    rdfs:comment "The allowance/charge is associated with the invoice message (inverse of hasAllowanceCharge)." .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TransportDetails ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an invoice message to transport details." ;
    owl:inverseOf :isTransportDetailsOfInvoiceMessage .

:isTransportDetailsOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :TransportDetails ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "Transport Details of Invoice Message" ;
    rdfs:comment "The transport details are associated with the invoice message (inverse of hasTransportDetails)." .

:hasPriceDetails a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :PriceDetails ;
    rdfs:label "has price details" ;
    rdfs:comment "Links a line item to its price details (PRI segment)." ;
    owl:inverseOf :isPriceDetailsOfLineItem .

:isPriceDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :PriceDetails ;
    rdfs:range :LineItem ;
    rdfs:label "Price Details of Line Item" ;
    rdfs:comment "The price details are associated with a line item (inverse of hasPriceDetails)." .

:hasDutyTaxFeeDetails a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DutyTaxFeeDetails ;
    rdfs:label "has duty/tax/fee details" ;
    rdfs:comment "Links a line item to its tax/duty/fee details (TAX segment)." ;
    owl:inverseOf :isDutyTaxFeeDetailsOfLineItem .

:isDutyTaxFeeDetailsOfLineItem a owl:ObjectProperty ;
    rdfs:domain :DutyTaxFeeDetails ;
    rdfs:range :LineItem ;
    rdfs:label "Duty/Tax/Fee Details of Line Item" ;
    rdfs:comment "The duty/tax/fee details are associated with a line item (inverse of hasDutyTaxFeeDetails)." .

:hasPackage a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Package ;
    rdfs:label "has package" ;
    rdfs:comment "Links a line item to packaging details (PAC segment)." ;
    owl:inverseOf :isPackageOfLineItem .

:isPackageOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Package ;
    rdfs:range :LineItem ;
    rdfs:label "Package of Line Item" ;
    rdfs:comment "The package is associated with a line item (inverse of hasPackage)." .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :AdditionalProductID ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links an item to its additional product IDs (PIA segment)." ;
    owl:inverseOf :isAdditionalProductIDOfItem .

:isAdditionalProductIDOfItem a owl:ObjectProperty ;
    rdfs:domain :AdditionalProductID ;
    rdfs:range :Item ;
    rdfs:label "Additional Product ID of Item" ;
    rdfs:comment "The additional product ID is associated with an item (inverse of hasAdditionalProductID)." .

:hasItemDescription a owl:ObjectProperty ;
    rdf:type owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemDescription ;
    rdfs:label "has item description" ;
