    rdfs:range :RFF_Reference .

:hasALC a owl:ObjectProperty ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Connects a SummarySection to its ALC_AllowanceCharge segments." ;
    rdfs:domain :SummarySection ;
    rdfs:range :ALC_AllowanceCharge .

:hasPRI a owl:ObjectProperty ;
