    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "An OWL2 DL ontology for UN/EDIFACT D96A INVOIC messages, including all mandatory segment classes, qualifiers, and hierarchical groupings as required by EANCOM and EN 16931-1." .

#################################################################
