    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            :Message
            [ a owl:Restriction ; owl:onProperty :hasHeaderSection ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass :HeaderSection ]
            [ a owl:Restriction ; owl:onProperty :hasDetailSection ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass :DetailSection ]
            [ a owl:Restriction ; owl:onProperty :hasSummarySection ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass :SummarySection ]
        )
    ] .

